17:   return <div className="history-view"><div className="history-view-heading"><div><div className="section-kicker">YOUR LOCAL GALLERY</div><h2>Made by you <span>{history.length}</span></h2></div><p><LockKeyhole size={13}/> Only on this device</p></div><div className="history-grid">{history.map(item => <article key={item.id} className={`history-item ${selected?.id === item.id ? 'chosen' : ''}`}><button className="history-thumb" onClick={() => onSelect(item)}><video src={item.url} muted preload="metadata"/><span className="history-play"><Play size={13} fill="currentColor"/></span></button><div className="history-item-info"><button onClick={() => onSelect(item)} className="history-title">{item.prompt}</button><span>{new Date(item.created).toLocaleDateString()} <i>·</i> {item.duration}s · {item.ratio}</span><button className="delete-history" onClick={() => onDelete(item.id)} aria-label="Delete video"><X size={14}/></button></div></article>)}</div>{selected && <div className="history-selected"><div><span className="section-kicker">SELECTED VIDEO</span><p>{selected.prompt}</p></div><button className="download-button" onClick={() => downloadEntry(selected)}><ArrowDownToLine size={15}/> Download MP4</button></div>}</div>
