@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

:root{font-family:'DM Sans',sans-serif;color:#eeeef0;background:#111214;font-synthesis:none;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;font-optical-sizing:auto;font-weight:400;--muted:#85858c;--line:#303135;--panel:#1a1b1e;--accent:#d9f36a;--accent-dark:#b2cf45}
